import type {SyntheticEvent} from 'react'
import * as React from 'react'
import {Suspense, useEffect} from 'react'
import {EntryPointContainer} from 'react-relay'

import {useEntryPointLoaderWithEnvironment} from '../../../../../../hooks/relay/useEntryPointLoaderWithEnvironment'
import CommonPopup from '../../../components/CommonPopup/CommonPopup'
import {EditAgentPoolFormEntryPoint} from '../../../components/EditAgentPoolForm/EditAgentPoolForm.entryPoint'
import type {AgentPool} from '../../AgentPoolPage.types'

type Props = {
  agentPool: AgentPool
  onUpdate: () => void
  onRemove: () => void
  onClose: () => void
  hidden: boolean
}

export default function EditAgentPoolPopup({
  agentPool,
  onUpdate,
  onRemove,
  onClose,
  hidden,
}: Props) {
  const [entryPoint, loadEntryPoint, disposeEntryPoint] = useEntryPointLoaderWithEnvironment(
    EditAgentPoolFormEntryPoint,
  )
  useEffect(() => {
    if (process.env.NODE_ENV === 'test') {
      // load entrypoint for storyshots
      loadEntryPoint(true)
    }
  }, [loadEntryPoint])
  const handleClose = React.useCallback(
    (e?: Event | SyntheticEvent) => {
      if (e?.target instanceof HTMLElement && e.target.closest('[role="dialog"]') == null) {
        onClose()
        disposeEntryPoint()
      }
    },
    [disposeEntryPoint, onClose],
  )
  return (
    <CommonPopup
      top={4}
      hidden={hidden}
      onShow={() => loadEntryPoint({})}
      onClose={handleClose}
      header={'Edit Agent Pool'}
      content={
        entryPoint && (
          <Suspense>
            <EntryPointContainer
              entryPointReference={entryPoint}
              props={{
                agentPool,
                onUpdate,
                onClose,
                onRemove,
              }}
            />
          </Suspense>
        )
      }
    />
  )
}
