import alert from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import classNames from 'classnames'
import * as React from 'react'
import {useMutation} from 'react-relay'

import type {AssignAgentsDialogBulkMoveItemsToAgentPoolMutation} from '../__generated__/AssignAgentsDialogBulkMoveItemsToAgentPoolMutation.graphql'
import {bulkMoveItemsToAgentPool} from '../AssignAgentsDialog.queries'

import styles from './AssignAgentsButtons.module.css'

type Props = {
  agentPoolRawId: string
  authorizedAgentRawIds: Array<string>
  unauthorizedAgentRawIds: Array<string>
  agentTypeRawIds: Array<string>
  onAssign?: () => void
  className?: string | undefined
  disabled?: boolean
}

export default function AssignAgentsButtons({
  className,
  disabled,
  agentTypeRawIds,
  authorizedAgentRawIds,
  unauthorizedAgentRawIds,
  agentPoolRawId,
  onAssign,
}: Props): React.ReactElement | null {
  const [commit, isInFlight] =
    useMutation<AssignAgentsDialogBulkMoveItemsToAgentPoolMutation>(bulkMoveItemsToAgentPool)

  const assignItemsToPool = React.useCallback(
    (shouldAuthorize: boolean) => {
      commit({
        variables: {
          agentTypeRawIds,
          authorizedAgentRawIds: shouldAuthorize
            ? authorizedAgentRawIds
            : [...authorizedAgentRawIds, ...unauthorizedAgentRawIds],
          unauthorizedAgentRawIds: shouldAuthorize ? unauthorizedAgentRawIds : [],
          agentPoolRawId,
        },
        onCompleted: (response, errors) => {
          if (errors == null) {
            onAssign?.()
          } else {
            errors.forEach(error => alert.error(error.message))
          }
        },
        onError: error => {
          alert.error(error.message)
        },
      })
    },
    [
      commit,
      agentTypeRawIds,
      authorizedAgentRawIds,
      unauthorizedAgentRawIds,
      agentPoolRawId,
      onAssign,
    ],
  )

  const onAssignClick = React.useCallback(() => {
    assignItemsToPool(false)
  }, [assignItemsToPool])

  const onAssignAndAuthoriseClick = React.useCallback(() => {
    assignItemsToPool(true)
  }, [assignItemsToPool])

  return (
    <>
      <Button
        primary
        loader={isInFlight}
        className={classNames(className, styles.assign)}
        onClick={onAssignClick}
        disabled={disabled}
      >
        {'Assign'}
      </Button>
      <Button
        loader={isInFlight}
        className={className}
        onClick={onAssignAndAuthoriseClick}
        disabled={disabled || unauthorizedAgentRawIds.length === 0}
      >
        {'Assign & Authorise'}
      </Button>
    </>
  )
}
