import alert from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import * as React from 'react'
import {useMutation} from 'react-relay'

import type {AgentPoolPageBulkAssignProjectWithAgentPoolMutation} from '../../../../__generated__/AgentPoolPageBulkAssignProjectWithAgentPoolMutation.graphql'
import {bulkAssignProjectWithAgentPool} from '../../../../AgentPoolPage.queries'

type Props = {
  agentPoolRawId: string
  projectRawIds: string[]
  exclusively: boolean
  onAssign: () => void
  className?: string | undefined
  disabled?: boolean
}

export default function AssignProjectsButton({
  className,
  agentPoolRawId,
  projectRawIds,
  exclusively,
  onAssign,
  disabled,
}: Props): React.ReactElement | null {
  const [commit, isInFlight] = useMutation<AgentPoolPageBulkAssignProjectWithAgentPoolMutation>(
    bulkAssignProjectWithAgentPool,
  )

  const onClick = React.useCallback(() => {
    commit({
      variables: {projectRawIds, agentPoolRawId, exclusively},
      onCompleted: (response, errors) => {
        if (errors == null) {
          onAssign()
        } else {
          errors.forEach(error => alert.error(error.message))
        }
      },
      onError: error => {
        alert.error(error.message)
      },
    })
  }, [agentPoolRawId, commit, exclusively, onAssign, projectRawIds])

  return (
    <Button primary loader={isInFlight} className={className} onClick={onClick} disabled={disabled}>
      {'Assign'}
    </Button>
  )
}
