import projectIcon from '@jetbrains/icons/project.svg'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'

import {getProjectHref} from '../../../../../routes'
import {toProjectId} from '../../../../../types'
import MatchingTitle from '../../../../common/MatchingItem/MatchingItem'
import Popup from '../../../../common/Popup/Popup.lazy'
import RouterLink from '../../../../common/RouterLink/RouterLink'
import type {AgentPoolProjectsTreeProjectItem} from '../AgentPoolPage.types'

import type {PathProps, PathItemContainerProps, ItemComponentProps} from './ProjectPath.types'

import styles from './ProjectPath.module.css'

const stopPropagation = (e: React.MouseEvent) => e.stopPropagation()

function ProjectContent({searchQuery, projectItem}: ItemComponentProps) {
  const {name, matching} = projectItem
  return (
    <>
      <span className={styles.icon}>
        <SvgIcon icon={projectIcon} />
      </span>
      {matching ? <MatchingTitle searchQuery={searchQuery}>{name}</MatchingTitle> : name}
    </>
  )
}

export function ProjectLine({projectItem, searchQuery, className}: ItemComponentProps) {
  return (
    <span className={className} title={projectItem.name}>
      <ProjectContent projectItem={projectItem} searchQuery={searchQuery} />
    </span>
  )
}

function ProjectLink({projectItem, searchQuery, className}: ItemComponentProps) {
  return (
    <RouterLink
      onClick={stopPropagation}
      to={getProjectHref(toProjectId(projectItem.rawId))}
      className={classNames(styles.link, className)}
      title={projectItem.name}
    >
      <ProjectContent projectItem={projectItem} searchQuery={searchQuery} />
    </RouterLink>
  )
}

function PathItemContainer({
  projectItem,
  parentItems,
  searchQuery,
  className,
  itemClassName,
  itemComponent: ItemComponent = ProjectLink,
}: PathItemContainerProps) {
  return (
    <div className={classNames(className, styles.pathItem)}>
      {parentItems.length > 0 ? (
        <Dropdown
          className={styles.parentsDropDownAnchor}
          anchor={<span className={styles.ellipsis}>{'...'}</span>}
          hoverShowTimeOut={300}
          hoverHideTimeOut={300}
          clickMode={false}
          hoverMode
        >
          <Popup left={-1} directions={[Directions.TOP_RIGHT, Directions.BOTTOM_RIGHT]}>
            <div className={styles.parentsPopup}>
              {parentItems.map((parentItem, i) => (
                <React.Fragment key={parentItem.rawId}>
                  <ItemComponent projectItem={parentItem} searchQuery={searchQuery} />
                  {i < parentItems.length - 1 ? (
                    <span className={styles.separator}>{'/'}</span>
                  ) : null}
                </React.Fragment>
              ))}
            </div>
          </Popup>
        </Dropdown>
      ) : null}
      {parentItems.length > 0 ? <span className={styles.separator}>{'/'}</span> : null}
      <ItemComponent
        projectItem={projectItem}
        searchQuery={searchQuery}
        className={itemClassName}
      />
    </div>
  )
}

export default function ProjectPath({
  parentItems,
  projectItem,
  searchQuery,
  itemContainerClassName,
  itemClassName,
  itemComponent,
  className,
  style,
  onClick,
}: PathProps) {
  const accumulatedParentItems: Array<AgentPoolProjectsTreeProjectItem> = []
  return (
    <span
      className={classNames(styles.path, className)}
      style={style}
      onClick={onClick}
      role={'presentation'}
    >
      <PathItemContainer
        projectItem={projectItem}
        searchQuery={searchQuery}
        className={classNames(itemContainerClassName, styles.targetItem)}
        itemClassName={itemClassName}
        parentItems={parentItems}
        itemComponent={itemComponent}
      />
      {parentItems
        .map(parentItem => {
          const pathItem = (
            <PathItemContainer
              projectItem={parentItem}
              parentItems={[...accumulatedParentItems]}
              key={parentItem.rawId}
              searchQuery={searchQuery}
              className={classNames(itemContainerClassName, styles.parentItemContainer)}
              itemClassName={classNames(styles.parentItem, itemClassName)}
              itemComponent={itemComponent}
            />
          )

          accumulatedParentItems.push(parentItem)

          return pathItem
        })
        .reverse()}
    </span>
  )
}
