import closeIcon from '@jetbrains/icons/close.svg'
import alert from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Confirm from '@jetbrains/ring-ui-built/components/confirm/confirm'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import * as React from 'react'
import type {SyntheticEvent} from 'react'
import {useMutation} from 'react-relay'

import PopupMenu from '../../../../../common/Popup/PopupMenu'
import type {AgentPoolPageUnassignProjectFromAgentPoolMutation} from '../../__generated__/AgentPoolPageUnassignProjectFromAgentPoolMutation.graphql'
import {unassignProjectFromAgentPool} from '../../AgentPoolPage.queries'
import type {AgentPoolProjectsTreeProjectItem} from '../../AgentPoolPage.types'
import {stopPropagation} from '../../AgentPoolPage.utils'

import styles from './DiassociateProjectButton.module.css'

type Props = {
  agentPoolRawId: string
  projectItem: AgentPoolProjectsTreeProjectItem
  onCompleted: (projectItem: AgentPoolProjectsTreeProjectItem, recursively: boolean) => void
}

function DiassociateProjectButton({agentPoolRawId, projectItem, onCompleted}: Props) {
  const isAssociatedWithSinglePool = projectItem.agentPools.length <= 1
  const [showUnassignConfirm, setShowUnassignConfirm] = React.useState(false)
  const [shouldUnassignRecursively, setUnassignRecursivery] = React.useState(false)
  const [commitUnassign, isUnassignmentInFlight] =
    useMutation<AgentPoolPageUnassignProjectFromAgentPoolMutation>(unassignProjectFromAgentPool)

  const unassign = React.useCallback(
    (recursively: boolean) => {
      commitUnassign({
        variables: {
          agentPoolRawId,
          projectRawId: projectItem.rawId,
          recursively,
        },
        onCompleted: (response, errors) => {
          if (errors == null) {
            onCompleted(projectItem, recursively)
          } else {
            errors.forEach(error => alert.error(error.message))
          }
        },
        onError: error => {
          alert.error(error.message)
        },
      })
    },
    [commitUnassign, agentPoolRawId, projectItem, onCompleted],
  )

  const handleUnassignProjectRecursively = React.useCallback(
    (event: Event | SyntheticEvent) => {
      event.stopPropagation()

      if (isAssociatedWithSinglePool) {
        setUnassignRecursivery(true)
        setShowUnassignConfirm(true)
      } else {
        unassign(true)
      }
    },
    [isAssociatedWithSinglePool, setShowUnassignConfirm, unassign],
  )

  const handleUnassignProject = React.useCallback(
    (event: SyntheticEvent | Event) => {
      event.stopPropagation()

      if (isAssociatedWithSinglePool) {
        setUnassignRecursivery(false)
        setShowUnassignConfirm(true)
      } else {
        unassign(false)
      }
    },
    [isAssociatedWithSinglePool, setShowUnassignConfirm, unassign],
  )

  const handleConfirm = React.useCallback(
    (event: SyntheticEvent) => {
      event.stopPropagation()

      unassign(shouldUnassignRecursively)
      setShowUnassignConfirm(false)
    },
    [shouldUnassignRecursively, unassign],
  )

  const onRejectDelete = React.useCallback((event?: SyntheticEvent) => {
    event?.stopPropagation()
    setShowUnassignConfirm(false)
  }, [])

  if (isUnassignmentInFlight) {
    return <LoaderInline className={styles.loader} />
  }

  return (
    <>
      {projectItem.children.length > 0 ? (
        <div onClick={stopPropagation} role="presentation">
          <Dropdown
            anchor={
              <IconButton icon={closeIcon} className={styles.unassignIcon} title="Dissociate" />
            }
          >
            <PopupMenu
              data={[
                {
                  label: 'Unassign project with all subprojects',
                  onClick: (_item: unknown, event: Event | SyntheticEvent) =>
                    handleUnassignProjectRecursively(event),
                },
                {
                  label: 'Unassign only this project',
                  onClick: (_item: unknown, event: Event | SyntheticEvent) => {
                    handleUnassignProject(event)
                  },
                },
              ]}
            />
          </Dropdown>
        </div>
      ) : (
        <IconButton
          icon={closeIcon}
          className={styles.unassignIcon}
          title="Dissociate"
          onClick={handleUnassignProject}
        />
      )}
      {isAssociatedWithSinglePool && (
        <Confirm
          text={
            shouldUnassignRecursively
              ? 'Dissociate this project with all subprojects?'
              : 'Dissociate this project?'
          }
          description={
            <>
              <p>
                {'You are about to dissociate\u00a0project\u00a0'}
                <strong>{`${projectItem?.name ?? ''}`}</strong>
                {shouldUnassignRecursively
                  ? '\u00a0with all subprojects\u00a0from their last\u00a0pool '
                  : '\u00a0from its last\u00a0pool '}
                <em>{`${projectItem?.agentPools[0].name}.`}</em>
              </p>
              <p>
                {
                  'This is the only\u00a0pool that is associated with this\u00a0project. If you dissociate it no builds of the\u00a0project can be started until you add it to another\u00a0pool.'
                }
              </p>
              <p>{'Are you sure you want to continue?'}</p>
            </>
          }
          confirmLabel="Yes"
          rejectLabel="Cancel"
          show={showUnassignConfirm}
          onConfirm={handleConfirm}
          onReject={onRejectDelete}
        />
      )}
    </>
  )
}

export default DiassociateProjectButton
